mapper.select:
SELECT

FROM SysAppVersion a WHERE 1 = 1

    and a.deviceType like CONCAT('%',#{deviceType}, '%')


    and a.buildVersion like CONCAT('%',#{buildVersion}, '%')


    and a.appVersion like CONCAT('%',#{appVersion}, '%')


    and a.canSupport  = #{canSupport}


    and a.checkStatus = #{checkStatus}


    and a.createBy = #{createBy}

ORDER BY a.id DESC
